<?php $items=all('enderecos');$edit=isset($_GET['edit'])?one('enderecos',(int)$_GET['edit']):null; ?>
<div class="two-col"><section class="panel"><div class="panel-header"><div><h2><?=$edit?'Editar endereço':'Cadastrar endereço'?></h2><p>Utilizado como origem ou destino do frete</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_address"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>">
<label>Nome / identificação<input class="form-control" name="nome" required maxlength="150" placeholder="Ex.: Fábrica Toledo" value="<?=h($edit['nome']??'')?>"></label>
<div class="form-row"><label>Cidade<input class="form-control" name="cidade" required maxlength="120" placeholder="Toledo" value="<?=h($edit['cidade']??'')?>"></label><label>UF<input class="form-control" name="uf" required minlength="2" maxlength="2" placeholder="PR" value="<?=h($edit['uf']??'')?>"></label></div>
<label>Logradouro (opcional)<input class="form-control" name="logradouro" maxlength="255" placeholder="Rua, número e bairro" value="<?=h($edit['logradouro']??'')?>"></label>
<label>CEP (opcional)<input class="form-control" name="cep" maxlength="12" placeholder="85900-000" value="<?=h($edit['cep']??'')?>"></label>
<div class="form-actions"><button class="btn btn-purple" type="submit">✓ &nbsp;Salvar endereço</button><?php if($edit):?><a class="btn btn-outline-secondary" href="index.php?page=enderecos">Cancelar</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-header"><div><h2>Endereços cadastrados</h2><p><?=count($items)?> locais disponíveis</p></div></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Local</th><th>Cidade / UF</th><th>CEP</th><th></th></tr></thead><tbody>
<?php foreach($items as $x):?><tr><td><b><?=h($x['nome'])?></b></td><td><?=h($x['cidade'])?> / <?=h($x['uf'])?></td><td><?=h($x['cep']?:'—')?></td><td class="action-cell"><a class="text-link" href="index.php?page=enderecos&amp;edit=<?=$x['id']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir este endereço?');"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="enderecos"><input type="hidden" name="id" value="<?=$x['id']?>"><button type="submit" class="link-danger">Excluir</button></form></td></tr><?php endforeach;?>
<?php if(!$items):?><tr><td colspan="4" class="empty-state">Nenhum endereço cadastrado.</td></tr><?php endif;?></tbody></table></div></section></div>
